const missionInfo={wins:{title:'리그 3승',description:'이번 과제를 시작한 뒤 리그에서 3번 승리',target:3,reward:20000,unit:'승'},growth:{title:'한 선수의 주요 능력 +3',description:'훈련과 출전 경험으로 한 선수를 성장시키기',target:3,reward:15000,unit:'성장'},youth:{title:'유소년에게 270분',description:'센터 출신 선수 한 명에게 출전 기회 주기',target:270,reward:25000,unit:'분'}};
let scoutPosition='FW',reportCycle=null;
function missionCards(){
 const progress=C.progress(season);
 return Object.entries(missionInfo).map(([key,info])=>{const earned=season.career.missions[key],n=progress[key];return `<article class="mission-card ${earned!==null?'achieved':''}"><div class="mission-top"><span>${earned!==null?'달성 · '+earned+'R':'시즌 과제'}</span><b>${moneyLabel(info.reward)}</b></div><h3>${info.title}</h3><p>${info.description}</p><div class="mission-progress"><i style="width:${Math.min(n/info.target,1)*100}%"></i></div><small>${key==='growth'?'주요 능력 +':''}${n} / ${info.target}${key==='wins'?'승':key==='youth'?'분':''} · ${earned!==null?'보상 지급 완료':'경기 결과 확정 때 자동 지급'}</small></article>`;}).join('');
}
function renderCareer(){
 const career=season.career,finance=season.finance,ready=state?.phase==='prep'&&state.minute===0&&season.competition==='league'&&season.round<14,cycle=season.round<7?1:2,done=career.reports.some(r=>r.cycle===cycle),enough=finance.balance>=12000,available=ready&&!done&&enough;
 $('board-tasks').innerHTML=`<div class="panel-heading"><h2>이사회 과제</h2><button id="open-academy" class="text-button">유소년 센터 →</button></div><div class="mission-grid">${missionCards()}</div>`;
 $('open-academy').onclick=()=>setView('academy');
 if(typeof view!=='undefined'&&view!=='academy')return;
 $('academy-overview').innerHTML=`<div class="academy-hero"><div><div class="eyebrow">BRYNWELL ACADEMY / SEASON ${String(season.year).padStart(2,'0')}</div><h1>우리의 다음 주인공.</h1><p>아직 이름 없는 재능에게 첫 기회를 주세요.<br>기본기, 빠른 발, 성장 가능성을 비교해 다음 주인공을 고르세요.</p></div><div class="academy-badge" aria-hidden="true"><span>BR</span><b>ACADEMY</b><small>THE NEXT WAVE</small></div></div><div class="scout-panel"><div class="scout-copy"><div class="eyebrow">${cycle===1?'FIRST HALF / 1–7R':'SECOND HALF / 8–14R'}</div><h2>${done?'보고서가 도착했습니다.':'어떤 포지션의 재능이 필요할까요?'}</h2><p>전반기와 후반기마다 한 번 · 스카우트 비용 £12,000 · 후보 3명<br>현재 구단 자금 ${finance.balance<0?'−':''}${moneyLabel(finance.balance)}</p></div><div class="scout-actions"><label for="scout-position" class="sr-only">스카우트 포지션</label><select id="scout-position" ${available?'':'disabled'}><option value="GK">GK · 골키퍼</option><option value="DEF">DEF · 수비수</option><option value="MID">MID · 미드필더</option><option value="FW">FW · 공격수</option></select><button id="send-scout" class="${available?'primary':'secondary'}" ${available?'':'disabled'}>${season.competition!=='league'?'다음 리그 준비 때 탐색':done?'이번 반기 탐색 완료':season.round===14?'다음 시즌에 탐색':!ready?'경기 준비 때 탐색':!enough?'스카우트 자금 부족':'£12,000으로 스카우트 보내기'}</button></div></div>`;
 $('scout-position').value=career.reports.find(r=>r.cycle===cycle)?.pos||scoutPosition;$('scout-position').onchange=e=>{scoutPosition=e.target.value;};
 $('send-scout').onclick=()=>action(()=>{season=S.scout(season,scoutPosition);state=season.match;reportCycle=cycle;});
 if(!career.reports.length){$('academy-reports').innerHTML=`<div class="academy-empty"><div class="empty-line" aria-hidden="true"></div><h2>첫 스카우트 보고서를 기다립니다.</h2><p>필요한 포지션을 정하면 서로 다른 강점을 가진 유망주 3명을 찾아옵니다.<br>보고서를 비교하고 같은 포지션 선수를 내보내 1군에 등록하세요.</p></div>`;}
 else {
  if(!career.reports.some(r=>r.cycle===reportCycle))reportCycle=career.reports.at(-1).cycle;
  const report=career.reports.find(r=>r.cycle===reportCycle),locked=finance.transferWeek===season.year+'-'+season.round;
  $('academy-reports').innerHTML=`<div class="report-tabs" aria-label="스카우트 보고서">${career.reports.map(r=>`<button data-report="${r.cycle}" aria-pressed="${r.cycle===reportCycle}">${r.cycle===1?'전반기':'후반기'} · ${r.pos} 보고서</button>`).join('')}</div><div class="panel-heading"><h2>${report.round}R에 찾은 세 가지 가능성</h2><span>원하는 선수에게 첫 기회를</span></div><div class="academy-grid">${report.candidates.map(identity=>{
   const person=F.identityProfile(identity),owned=Object.values(season.squad).find(p=>p.identity===identity),candidate=owned||person,used=finance.marketUsed.includes(identity),same=Object.values(season.squad).filter(p=>p.pos===person.pos),key=S.primaryKey(person);
   let slot=outgoingChoices[identity];if(!same.some(p=>p.id===slot)){slot=[...same].sort((a,b)=>Number(state?.lineup.includes(a.id))-Number(state?.lineup.includes(b.id))||a[key]-b[key])[0].id;outgoingChoices[identity]=slot;}
   const quote=E.quote(season,identity,slot),talkBlocked=recruitmentTalkBlock(slot),blocked=!ready||locked||used||owned||talkBlocked||quote.balanceAfter<0,style=person.academyVariant===1?'준비된 기본기':person.academyVariant===2?'긴 성장 가능성':'고른 능력';
   return `<article class="market-card academy-candidate"><div class="candidate-top"><span class="position">${person.pos} · ${person.age+season.year-person.academyYear}세</span><span class="prospect">${owned?'우리 유소년':style}</span></div><div class="candidate-identity">${Portraits.html(candidate,{size:'large'})}<h2>${person.name}</h2></div><button class="profile-inline-button" data-player-detail="${playerUiText(candidate.identity)}" aria-label="${playerUiText(candidate.name)} 선수 상세 보기">선수 상세 카드 ↗</button>${playerCharacterMarkup(candidate)}<p class="candidate-age">1군 첫 계약 · 주급 ${moneyLabel(person.wage)}</p><div class="candidate-stats"><div><span>주요 능력</span><b>${candidate[key]}</b></div><div><span>성장 한계</span><b>${candidate.potential}</b></div><div><span>속도</span><b>${candidate.speed}</b></div><div><span>지구력</span><b>${candidate.endurance}</b></div></div>${owned?`<div class="contract-note">1군에 등록됐습니다.<br>이번 시즌 전체 대회 출전 ${career.minutes[identity]||0}분 · 주요 능력 ${owned[key]}</div>`:`<div class="candidate-fee">등록 이적료 <b>${moneyLabel(person.fee)}</b></div><label for="academy-out-${identity}">보낼 ${person.pos} 선수</label><select id="academy-out-${identity}" data-academy-out="${identity}" ${!ready||locked||used?'disabled':''}>${same.map(p=>`<option value="${p.id}" ${p.id===slot?'selected':''}>${p.name} · 주요 ${p[key]} · ${moneyLabel(E.resale(p))}</option>`).join('')}</select>${recruitComparisonMarkup(person,season.squad[slot])}<div class="deal-lines"><span>보낼 선수 평가액 <b>−${moneyLabel(quote.credit)}</b></span><span>수수료 <b>${moneyLabel(quote.commission)}</b></span><span>${quote.cost<0?'구단에 돌아오는 자금':'등록에 필요한 자금'} <b>${moneyLabel(quote.cost)}</b></span><span>주급 변화 <b>${signedMoney(quote.wageChange)}</b></span><span>등록 후 자금 <b class="${quote.balanceAfter<0?'loss':''}">${quote.balanceAfter<0?'−':''}${moneyLabel(quote.balanceAfter)}</b></span></div><button type="button" class="secondary finance-plan-compare" data-academy-finance="${identity}">등록 후 자금 계획 비교</button>`}<button class="${blocked?'secondary':'primary'}" data-promote="${identity}" ${blocked?'disabled':''}>${owned?'1군 선수로 뛰는 중':used?'이번 시즌 계약 완료':!ready?'다음 리그 준비 때 등록':locked?'이번 주 영입 완료':talkBlocked?'팀 대화 완료 · 다음 경기 전 가능':quote.balanceAfter<0?'등록 자금 부족':person.name+' 1군 등록'}</button>${ready&&!locked&&!used&&!owned&&talkBlocked?'<p class="finance-note market-talk-reason" role="status">'+recruitmentTalkReason()+'</p>':''}</article>`;
  }).join('')}</div><p class="finance-note">1군 등록은 영입 시장과 같은 주간 영입 기회를 사용합니다. 기존 선수 한 명을 내보내며, 새 선수의 출전 경험은 0부터 시작합니다.</p>`;
  $('academy-reports').querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{reportCycle=Number(b.dataset.report);renderCareer();});
  $('academy-reports').querySelectorAll('[data-academy-out]').forEach(select=>select.onchange=()=>{outgoingChoices[select.dataset.academyOut]=select.value;renderCareer();});
  $('academy-reports').querySelectorAll('[data-academy-finance]').forEach(button=>button.onclick=()=>openFinancePlan(button.dataset.academyFinance,outgoingChoices[button.dataset.academyFinance]));
  $('academy-reports').querySelectorAll('[data-promote]').forEach(b=>b.onclick=()=>{if(b.disabled)return;action(()=>{season=S.recruit(season,b.dataset.promote,outgoingChoices[b.dataset.promote]);state=season.match;selected=null;});});
 }
 $('academy-tasks').innerHTML=`<div class="panel-heading"><h2>성장으로 답하는 이사회 과제</h2><span>${season.year}시즌</span></div><div class="mission-grid">${missionCards()}</div><p class="finance-note">과제는 매 시즌 새로 시작합니다.${career.originRound?' 이번 저장에서는 '+(career.originRound+1)+'R부터 새 과제를 집계합니다.':''} 이미 달성한 과제의 보상은 경기 결과 확정 때 한 번 지급하며, 선수와 구단 자금은 다음 시즌으로 이어집니다.</p>`;
}
